const nextConfig: NextConfig = {
  // react-dom/server is used by GanttTemplate.tsx (renderToStaticMarkup) for
  // server-side HTML generation. Marking react-dom as a server external package
  // tells Turbopack to resolve it from the Node.js runtime rather than bundling
  // it through the module-condition check, which would reject it in App Route
  // module graphs. This is required for the gantt-generate API route to import
  // server.ts → GanttTemplate.tsx at build time.
